xml.src:

import {InuInputPassword} from 'inugami-ng/components/inu-input-password';

interface UserForm {
  login: string;
  password: string;
}

@Component({
  templateUrl: './inu-input-text.view.html',
  styleUrls: ['./inu-input-text.view.scss'],
  imports: [
    InuInputPassword,
    //...
  ]
})
export class InuInputTextView {

  data = signal<string>('');
  userModel = signal<UserForm>({
    login   : '',
    password: '',
  });

  userForm: FieldTree<UserForm>  = form(this.userModel, (path) => {
     required(path.login);
     required(path.password);
  });


  constructor() {
      InuFormsUtils.onChanged(this.userModel)
                   .subscribe(value => {
        this.onChanged(value)
      });
  }

  private onValueChanged(value: UserForm) {
    this.data.set(JSON.stringify(value, null, 4));
  }
}
